const input = $input.first().json;
const OWNER = input.githubOwner || 'bisco401';
const REPO = input.githubRepo || '6ixo';
const BRANCH = input.githubBranch || 'main';
const CSV_PATH = input.csvPath || 'data/scraped-listings.csv';
const TOKEN = input.githubToken;
const DEFAULT_STATUS = input.defaultImportStatus || 'published';
const CRAWL4AI_URL = input.crawl4aiUrl;
const DETAIL_BATCH_SIZE = Math.max(1, Number(input.detailBatchSize || 8));
const REQUIRE_PHONE = String(input.requirePhone || 'true') === 'true';
const PHONE_AREA_CODES = new Set(String(input.allowedAreaCodes || '210,214,254,281,325,346,361,409,430,432,469,512,682,713,726,737,806,817,830,832,903,915,936,940,945,956,972,979').split(',').map((v) => v.trim()).filter(Boolean));
let SOURCES = [];
try {
  SOURCES = typeof input.sourcesJson === 'string' ? JSON.parse(input.sourcesJson || '[]') : input.sourcesJson;
} catch (error) {
  throw new Error('sourcesJson is not valid JSON in Set Config Here.');
}
if (!TOKEN || TOKEN === 'PASTE_GITHUB_TOKEN_HERE') throw new Error('Set GITHUB_TOKEN in n8n with repo contents permission.');
if (!CRAWL4AI_URL) throw new Error('Set CRAWL4AI_URL to your Crawl4AI /crawl endpoint.');
if (!Array.isArray(SOURCES) || !SOURCES.length) throw new Error('No Texas Craigslist sources configured.');

const httpRequest = async (options) => {
  const request = {
    method: options.method || 'GET',
    uri: options.url,
    url: options.url,
    headers: options.headers || {},
    body: options.body,
    json: options.json === true,
    resolveWithFullResponse: true,
    simple: false,
    timeout: options.timeout || 120000
  };
  try {
    const response = await this.helpers.httpRequest(request);
    const status = response.statusCode || response.status || 200;
    const body = response.body ?? response;
    return { status, ok: status >= 200 && status < 300, body };
  } catch (error) {
    const status = error.statusCode || error.status || error.response?.status || error.response?.statusCode || 500;
    const body = error.response?.body || error.response?.data || error.message || '';
    return { status, ok: status >= 200 && status < 300, body };
  }
};

const csvHeaders = ['id','status','target_surface','app_category','app_subcategory','title','price_text','price_value','currency','city','country','seller','phone','description','image_urls','source_site','source_url','scraped_at','make','model','trim','year','condition','transmission','color','mileage_km','attributes','source_availability','source_availability_checked_at','source_http_status','source_unavailable_reason','source_last_seen_at','source_resolved_url'];
const ghHeaders = { authorization: `Bearer ${TOKEN}`, accept: 'application/vnd.github+json', 'x-github-api-version': '2022-11-28' };
const strip = (value = '') => String(value || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#34;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();
const absUrl = (value, base) => {
  try { return new URL(String(value || ''), base || undefined).toString(); }
  catch { return String(value || '').trim(); }
};
const canonicalUrl = (value, base) => {
  const url = absUrl(value, base);
  try {
    const parsed = new URL(url);
    parsed.hash = '';
    parsed.search = '';
    return parsed.toString().replace(/\/$/, '');
  } catch {
    return url.replace(/#.*$/, '').replace(/\?.*$/, '').replace(/\/$/, '');
  }
};
const listingUrl = (href, base) => {
  const url = canonicalUrl(href, base);
  return /craigslist\.org\/.+\/\d{9,}\.html$/i.test(url) ? url : '';
};
const listingId = (url = '') => String(url || '').match(/\/(\d{9,})\.html(?:[?#].*)?$/)?.[1] || '';
const priceValue = (priceText = '') => {
  const parsed = Number(String(priceText || '').replace(/[^0-9.]/g, ''));
  return Number.isFinite(parsed) ? String(parsed) : '';
};
const normalizePhone = (text = '', blockedIds = []) => {
  const blocked = new Set(blockedIds.filter(Boolean));
  const phones = [];
  const seen = new Set();
  const matches = String(text || '').match(/(?:\+?1[\s.-]?)?(?:\(?[2-9]\d{2}\)?[\s.-]?)\d{3}[\s.-]?\d{4}/g) || [];
  for (const raw of matches) {
    let phone = raw.replace(/\D/g, '');
    if (phone.length === 11 && phone.startsWith('1')) phone = phone.slice(1);
    const area = phone.slice(0, 3);
    if (phone.length !== 10) continue;
    if (blocked.has(phone) || /^793/.test(phone)) continue;
    if (PHONE_AREA_CODES.size && !PHONE_AREA_CODES.has(area)) continue;
    if (!seen.has(phone)) {
      phones.push(phone);
      seen.add(phone);
    }
  }
  return phones.join(' | ');
};
const normalizeImageUrls = (html = '', base = '') => {
  const urls = [];
  for (const match of String(html || '').matchAll(/<(?:img|source)\b[^>]+(?:src|data-src|data-full-image|srcset)=["']([^"']+)["'][^>]*>/gi)) {
    const raw = String(match[1] || '').split(',').map((part) => part.trim().split(/\s+/)[0]).filter(Boolean);
    for (let url of raw) {
      url = absUrl(url, base).replace('_300x300.', '_1200x900.').replace('_600x450.', '_1200x900.');
      if (/^https?:\/\//i.test(url) && !/logo|avatar|icon|sprite|blank|map\d?\.craigslist/i.test(url) && !urls.includes(url)) urls.push(url);
    }
  }
  return urls.slice(0, 12);
};
const parseCsv = (text = '') => {
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  const pushCell = () => { row.push(cell); cell = ''; };
  const pushRow = () => { pushCell(); if (row.some((v) => String(v || '').trim())) rows.push(row); row = []; };
  const input = String(text || '').replace(/^\uFEFF/, '');
  for (let i = 0; i < input.length; i += 1) {
    const char = input[i];
    const next = input[i + 1];
    if (quoted) {
      if (char === '"' && next === '"') { cell += '"'; i += 1; }
      else if (char === '"') quoted = false;
      else cell += char;
    } else if (char === '"') quoted = true;
    else if (char === ',') pushCell();
    else if (char === '\n') pushRow();
    else if (char !== '\r') cell += char;
  }
  if (cell || row.length) pushRow();
  const headers = (rows.shift() || csvHeaders).map((h) => String(h || '').trim());
  return rows.map((values) => headers.reduce((acc, header, index) => { if (header) acc[header] = values[index] || ''; return acc; }, {}));
};
const csvEscape = (value = '') => {
  const text = String(value ?? '');
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};
const toCsv = (rows = []) => [csvHeaders.join(','), ...rows.map((row) => csvHeaders.map((header) => csvEscape(row[header] || '')).join(','))].join('\n') + '\n';
const getGithubCsv = async () => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}?ref=${BRANCH}`;
  const res = await httpRequest({ url, headers: ghHeaders, json: true });
  if (res.status === 404) return { sha: null, text: csvHeaders.join(',') + '\n' };
  if (!res.ok) throw new Error(`Could not read ${CSV_PATH}: ${res.status} ${typeof res.body === 'string' ? res.body : JSON.stringify(res.body)}`);
  const json = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
  return { sha: json.sha, text: Buffer.from(json.content || '', 'base64').toString('utf8') };
};
const putGithubCsv = async (text, sha) => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}`;
  const body = { message: 'Update Texas Craigslist listings', branch: BRANCH, content: Buffer.from(text, 'utf8').toString('base64'), ...(sha ? { sha } : {}) };
  const res = await httpRequest({ url, method: 'PUT', headers: { ...ghHeaders, 'content-type': 'application/json' }, body, json: true });
  if (!res.ok) throw new Error(`Could not update ${CSV_PATH}: ${res.status} ${typeof res.body === 'string' ? res.body : JSON.stringify(res.body)}`);
  return typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
};
const normalizeCrawlItems = (value) => {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap(normalizeCrawlItems);
  if (Array.isArray(value.results)) return value.results;
  if (Array.isArray(value.data)) return value.data;
  if (value.body) return normalizeCrawlItems(value.body);
  return [value];
};
const extractCandidateLinks = (source, html = '') => {
  const seen = new Set();
  const candidates = [];
  const base = source.base_url || source.list_url;
  for (const match of String(html || '').matchAll(/<a\b[^>]+href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
    const url = listingUrl(match[1], base);
    if (!url || seen.has(url)) continue;
    seen.add(url);
    const title = strip(match[2]);
    candidates.push({ url, title });
    if (candidates.length >= Number(source.max_candidates || 8)) break;
  }
  return candidates;
};
const crawlUrls = async (urls = []) => {
  if (!urls.length) return [];
  const res = await httpRequest({
    url: CRAWL4AI_URL,
    method: 'POST',
    body: {
      urls,
      browser_config: { headless: true, viewport: { width: 1440, height: 2200 }, verbose: false },
      crawler_config: { stream: false, cache_mode: 'bypass', wait_until: 'load', wait_for: 'css:body', page_timeout: 90000, delay_before_return_html: 1.5, scan_full_page: true, remove_overlay_elements: true, remove_consent_popups: true, flatten_shadow_dom: true }
    },
    json: true,
    timeout: 180000
  });
  if (!res.ok) throw new Error(`Crawl4AI failed: ${res.status} ${typeof res.body === 'string' ? res.body : JSON.stringify(res.body)}`);
  return normalizeCrawlItems(res.body);
};
const itemHtml = (item = {}) => item.html || item.cleaned_html || item.fit_html || item.markdown?.raw_markdown || item.markdown || item.fit_markdown || '';
const parseDetail = (source, item = {}) => {
  const sourceUrl = canonicalUrl(item.url || item.redirected_url || '', source.base_url || source.list_url);
  const html = itemHtml(item);
  const text = strip(html);
  const id = listingId(sourceUrl);
  const phone = normalizePhone(text, [id]);
  if (REQUIRE_PHONE && !phone) return null;
  const title = strip((html.match(/id=["']titletextonly["'][^>]*>([\s\S]*?)<\//i) || html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i) || [])[1] || item.title || '');
  if (!title) return null;
  const priceText = strip((html.match(/class=["'][^"']*price[^"']*["'][^>]*>([\s\S]*?)<\//i) || [])[1] || '');
  const description = strip((html.match(/id=["']postingbody["'][^>]*>([\s\S]*?)<\/section>/i) || html.match(/id=["']postingbody["'][^>]*>([\s\S]*?)<\/div>/i) || [])[1] || '').replace(/^QR Code Link to This Post\s*/i, '');
  const sellerRaw = strip((html.match(/class=["'][^"']*postinginfos[^"']*["'][^>]*>([\s\S]*?)<\/div>/i) || [])[1] || '');
  const images = normalizeImageUrls(html, sourceUrl);
  const scrapedAt = new Date().toISOString();
  return {
    id: `craigslist-${id || Math.abs([...sourceUrl].reduce((a, c) => ((a << 5) - a + c.charCodeAt(0)) | 0, 0))}`,
    status: DEFAULT_STATUS,
    target_surface: source.target_surface || 'marketplace',
    app_category: source.app_category || 'buy_sell',
    app_subcategory: source.app_subcategory || source.source_category || 'other',
    title,
    price_text: priceText,
    price_value: priceValue(priceText),
    currency: 'USD',
    city: source.city || '',
    country: source.country || 'United States',
    seller: 'Unknown',
    phone,
    description,
    image_urls: images.join('|'),
    source_site: 'Craigslist',
    source_url: sourceUrl,
    scraped_at: scrapedAt,
    make: '',
    model: '',
    trim: '',
    year: String(title.match(/\b(19|20)\d{2}\b/)?.[0] || ''),
    condition: 'good',
    transmission: String(text.match(/\b(Automatic|Manual)\b/i)?.[0] || ''),
    color: '',
    mileage_km: '',
    attributes: JSON.stringify({ parser: 'crawl4ai_texas_craigslist', sourceCategory: source.source_category || '', searchKeyword: source.search_keyword || '', province: source.province || 'TX', sellerRaw })
  };
};

const sourceListItems = await crawlUrls(SOURCES.map((source) => source.list_url));
const listByUrl = new Map();
for (const item of sourceListItems) listByUrl.set(canonicalUrl(item.url || item.redirected_url || ''), item);
const detailJobs = [];
const sourceSummary = [];
for (const source of SOURCES.filter((source) => source && source.enabled !== false)) {
  const key = canonicalUrl(source.list_url);
  const item = listByUrl.get(key) || Array.from(listByUrl.values()).find((entry) => canonicalUrl(entry.url || entry.redirected_url || '') === key);
  const html = item ? itemHtml(item) : '';
  if (!html) {
    sourceSummary.push({ source: source.name, status: 'empty', candidates: 0 });
    continue;
  }
  const candidates = extractCandidateLinks(source, html);
  sourceSummary.push({ source: source.name, status: candidates.length ? 'queued' : 'empty', candidates: candidates.length });
  for (const candidate of candidates) detailJobs.push({ source, url: candidate.url });
}
const detailRows = [];
for (let i = 0; i < detailJobs.length; i += DETAIL_BATCH_SIZE) {
  const batch = detailJobs.slice(i, i + DETAIL_BATCH_SIZE);
  const details = await crawlUrls(batch.map((job) => job.url));
  const sourceByUrl = new Map(batch.map((job) => [canonicalUrl(job.url), job.source]));
  for (const detail of details) {
    const url = canonicalUrl(detail.url || detail.redirected_url || '');
    const source = sourceByUrl.get(url) || batch.find((job) => canonicalUrl(job.url) === url)?.source;
    if (!source) continue;
    const row = parseDetail(source, detail);
    if (row) detailRows.push(row);
  }
}
const existing = await getGithubCsv();
const rowsByUrl = new Map(parseCsv(existing.text).map((row) => [String(row.source_url || '').trim(), row]));
let inserted = 0;
for (const row of detailRows) {
  const key = String(row.source_url || '').trim();
  if (!key) continue;
  rowsByUrl.set(key, { ...(rowsByUrl.get(key) || {}), ...row });
  inserted += 1;
}
const nextRows = Array.from(rowsByUrl.values()).sort((a, b) => String(b.scraped_at || '').localeCompare(String(a.scraped_at || '')));
await putGithubCsv(toCsv(nextRows), existing.sha);
const categoryCounts = {};
const cityCounts = {};
for (const row of detailRows) {
  categoryCounts[row.app_category] = (categoryCounts[row.app_category] || 0) + 1;
  cityCounts[row.city] = (cityCounts[row.city] || 0) + 1;
}
return [{ json: { status: 'success', sources: SOURCES.length, candidates: detailJobs.length, inserted, categoryCounts, cityCounts, sourceSummary } }];
